final class PortfolioMirrorChecks {
 static int count;
 interface Throwing{void run()throws Exception;}
 static void check(boolean b,String why){count++;if(!b)throw new AssertionError(why);}
 static void rejects(Throwing work,String why)throws Exception{boolean bad=false;try{work.run();}catch(Exception e){bad=true;}check(bad,why);}
 static void same(Object a,Object b,String why)throws Exception{check(PortfolioMirrorModel.equal(a,b),why);}
 static JSONObject context(JSONObject scope)throws Exception{return PortfolioMirrorModel.object("accounts",new JSONArray().put(scope.get("account")),"ledgers",new JSONArray().put(scope.get("ledger")),"instruments",scope.get("instruments"),"capturedAt",scope.get("capturedAt"),"sourceLabel",scope.get("sourceLabel"));}
 static void model(JSONObject fixture)throws Exception{
  JSONObject source=PortfolioMirrorModel.decode(fixture.getJSONObject("source").getString("rawUtf8"));same(source,fixture.getJSONObject("source"),"source full decode");JSONArray cases=fixture.getJSONArray("cases");for(int i=0;i<cases.length();i++){JSONObject sample=cases.getJSONObject(i),expected=sample.getJSONObject("draft"),input=context(expected.getJSONObject("scope")),parsed=PortfolioMirrorModel.decode(expected.getJSONObject("source").getString("rawUtf8"));JSONObject draft=PortfolioMirrorModel.prepare(parsed,expected.getJSONObject("mirror").getInt("snapshotIndex"),input,expected.getJSONObject("scope").getJSONObject("account").getString("id"),expected.getJSONArray("bindings"),expected.getJSONObject("options"));same(draft,expected,"full case "+sample.getString("label"));JSONObject record=PortfolioMirrorModel.version(draft,"2026-10-13T02:00:00Z");same(record,sample.getJSONObject("record"),"full version ID "+i);PortfolioMirrorModel.validateRecord(record);}
  JSONObject baseline=fixture.getJSONObject("draft"),input=fixture.getJSONObject("input");rejects(()->PortfolioMirrorModel.prepare(source,0,input,"b",baseline.getJSONArray("bindings"),baseline.getJSONObject("options")),"wrong explicit account");rejects(()->PortfolioMirrorModel.prepare(source,0,input,"p",baseline.getJSONArray("bindings"),baseline.getJSONObject("options")),"paper account");rejects(()->PortfolioMirrorModel.prepare(source,0,input,"a",new JSONArray(),baseline.getJSONObject("options")),"unbound identity");JSONObject both=new JSONObject(fixture.getJSONObject("raw").toString()).put("accountKey","acct-B");rejects(()->PortfolioMirrorModel.prepare(PortfolioMirrorModel.decode(both.toString()),0,input,"a",baseline.getJSONArray("bindings"),baseline.getJSONObject("options")),"conflicting account hints");
  JSONObject duplicate=new JSONObject(fixture.getJSONObject("raw").toString());duplicate.getJSONArray("holdings").put(duplicate.getJSONArray("holdings").get(0));rejects(()->PortfolioMirrorModel.decode(duplicate.toString()),"duplicate source");JSONObject broken=new JSONObject(fixture.getJSONObject("raw").toString());broken.getJSONArray("holdings").getJSONObject(0).put("quantity",120.5);rejects(()->PortfolioMirrorModel.decode(broken.toString()),"fractional shares");rejects(()->PortfolioMirrorModel.decode("{schema:'portfolio-mirror-input/v1'}"),"strict JSON");rejects(()->PortfolioMirrorModel.decode("code,name,quantity,costValue\n600000,浦发银行,100\n"),"CSV row missing cell");
  JSONObject record=fixture.getJSONObject("record");same(PortfolioMirrorModel.comparison(record,input,"2026-10-13T02:30:00Z"),fixture.getJSONObject("comparison"),"full comparison cross");JSONObject largeSource=PortfolioMirrorModel.decode(fixture.getString("largeRawUtf8")),largeDraft=PortfolioMirrorModel.prepare(largeSource,0,input,"a",baseline.getJSONArray("bindings"),baseline.getJSONObject("options")),large=PortfolioMirrorModel.version(largeDraft,"2026-10-13T03:00:00Z");check(large.getString("id").equals(fixture.getString("largeRecordId")),"large complete unknown original version ID");PortfolioMirrorModel.validateRecord(large);
  JSONObject tampered=new JSONObject(record.toString());tampered.getJSONObject("draft").getJSONObject("mirror").getJSONArray("holdings").getJSONObject(0).put("quantity",999);JSONObject td=tampered.getJSONObject("draft");td.put("reconciliation",PortfolioMirrorModel.reconcile(td.getJSONObject("mirror"),td.getJSONObject("scope")));tampered.remove("id");tampered.put("id",PortfolioMirrorModel.hash(tampered));rejects(()->PortfolioMirrorModel.validateRecord(tampered),"rehashed derived quantity drift");
 }
 static void cleanup(File file){for(String suffix:new String[]{"","-journal","-wal","-shm"})new File(file+suffix).delete();}
 // Store only, safe to run in worker. Fresh paths, not existing failed files.
 static String runStoreGuards(Context c)throws Exception{count=0;String token=UUID.randomUUID().toString();PortfolioMirrorStore fresh=new PortfolioMirrorStore(c,"mirror-fresh-"+token+".sqlite");File foreign=new File(c.getFilesDir(),"mirror-foreign-"+token+".sqlite");try{try(SQLiteDatabase db=SQLiteDatabase.openDatabase(fresh.filePath().getAbsolutePath(),null,SQLiteDatabase.OPEN_READONLY);Cursor q=db.rawQuery("PRAGMA application_id",null)){check(q.moveToFirst()&&q.getInt(0)==1347244595,"fresh actual PRAGMA appId written/consumed");}check(fresh.catalog().length()==0,"fresh independent schema ready");PortfolioMirrorStore reopened=new PortfolioMirrorStore(c,fresh.filePath().getName());check(reopened.catalog().length()==0,"fresh reopen marker guard");try(SQLiteDatabase db=SQLiteDatabase.openOrCreateDatabase(foreign,null)){db.execSQL("CREATE TABLE protected_table(value TEXT)");db.execSQL("INSERT INTO protected_table VALUES('keep')");}byte[]before=Files.readAllBytes(foreign.toPath());rejects(()->new PortfolioMirrorStore(c,foreign.getName()),"foreign appId0 rejected");check(Arrays.equals(before,Files.readAllBytes(foreign.toPath())),"foreign DB bytes unchanged");return "PortfolioMirror Android fresh/foreign guards PASS "+count;}finally{cleanup(fresh.filePath());cleanup(foreign);}}
 static String run(Context c,String text)throws Exception{count=0;JSONObject fixture=new JSONObject(text);model(fixture);int modelCount=count;String guardResult=runStoreGuards(c);count+=modelCount;PortfolioMirrorStore store=new PortfolioMirrorStore(c,"mirror-store-"+UUID.randomUUID()+".sqlite");try{JSONObject record=fixture.getJSONObject("record");String empty=store.catalogFingerprint();store.append(new JSONArray().put(record),empty);same(store.get(record.getString("id")),record,"immutable actual SQLite record");rejects(()->store.append(new JSONArray().put(record),empty),"stale catalog");PortfolioMirrorStore reopened=new PortfolioMirrorStore(c,store.filePath().getName());same(reopened.get(record.getString("id")),record,"atomic store reopen");JSONObject comparison=fixture.getJSONObject("comparison");store.append(new JSONArray().put(comparison),store.catalogFingerprint());same(store.get(comparison.getString("id")),comparison,"comparison linked original");JSONObject baseline=fixture.getJSONObject("draft"),largeSource=PortfolioMirrorModel.decode(fixture.getString("largeRawUtf8")),largeDraft=PortfolioMirrorModel.prepare(largeSource,0,fixture.getJSONObject("input"),"a",baseline.getJSONArray("bindings"),baseline.getJSONObject("options")),large=PortfolioMirrorModel.version(largeDraft,"2026-10-13T03:00:00Z");check(large.toString().getBytes(StandardCharsets.UTF_8).length>2*1024*1024,"real large record exceeds CursorWindow");store.append(new JSONArray().put(large),store.catalogFingerprint());same(store.get(large.getString("id")),large,"chunked full large version");same(store.get(large.getString("id")).getJSONObject("draft").getJSONObject("source").getString("rawUtf8"),fixture.getString("largeRawUtf8"),"full raw original exact");JSONObject view=new JSONObject().put("schema","portfolio-mirror-view/v1").put("largeSource",largeSource);store.saveView(view,new JSONObject());same(store.loadView(),view,"full large private sidecar");rejects(()->store.saveView(view,new JSONObject()),"stale sidecar");JSONObject nativeBackup=PortfolioMirrorModel.decode(store.exportText());check(nativeBackup.getJSONObject("original").getJSONArray("records").length()==3,"full evidence export");return "PortfolioMirror Android model/store PASS "+count+"; "+guardResult;}finally{cleanup(store.filePath());}}
 private static Button button(View view,String name){if(view instanceof Button&&name.equals(((Button)view).getText().toString()))return (Button)view;if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int i=0;i<g.getChildCount();i++){Button b=button(g.getChildAt(i),name);if(b!=null)return b;}}return null;}
 private static void click(PortfolioMirrorScreen screen,String name){Button b=button(screen,name);check(b!=null,"button "+name);b.performClick();}
 // Actual native View/Bundle/Parcel operations. MUST be called on main/UI thread.
 static String runScreen(Context c,String text)throws Exception{count=0;JSONObject fixture=new JSONObject(text);PortfolioMirrorStore store=new PortfolioMirrorStore(c,"mirror-screen-"+UUID.randomUUID()+".sqlite");final JSONObject[]opened={null};try{JSONObject input=fixture.getJSONObject("input");PortfolioMirrorScreen screen=new PortfolioMirrorScreen(c,store,()->new JSONObject(input.toString()),r->opened[0]=r);screen.setAccount("a");screen.previewImport(fixture.getString("largeRawUtf8"));check(store.catalog().length()==0,"preview no immutable versions");Spinner picker=(Spinner)screen.findViewWithTag("mirrorInstrument");check(picker.getSelectedItemPosition()==0,"bare code no automatic market/type choice");picker.setSelection(1);click(screen,"确认此行完整身份");((CheckBox)screen.findViewWithTag("mirrorAccountAck")).setChecked(true);click(screen,"预览差异");JSONObject state=store.loadView();check(state.getInt("mode")==2&&state.getJSONObject("prepared").length()>0,"actual difference preview");Bundle saved=screen.saveState();check(saved.size()==2,"Bundle marker only");Parcel parcel=Parcel.obtain();saved.writeToParcel(parcel,0);check(parcel.dataSize()<4096,"large source never Binder body");parcel.recycle();PortfolioMirrorScreen restored=new PortfolioMirrorScreen(c,store,()->new JSONObject(input.toString()),r->opened[0]=r);restored.restoreState(saved);same(store.loadView(),state,"rotation pending/body/full draft");restored.confirmImport();check(store.catalog().length()==1&&store.loadView().getJSONObject("pending").length()==0,"explicit independent save");click(restored,"精确K线");check(opened[0]!=null&&opened[0].getString("id").equals("SH:stock:600000")&&opened[0].getJSONObject("quote").getDouble("price")==0,"exact complete callback quote0");restored.setDarkTheme(true);int width=Math.round(900*c.getResources().getDisplayMetrics().density),height=Math.round(180*c.getResources().getDisplayMetrics().density);restored.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));restored.layout(0,0,width,height);check(restored.findViewWithTag("mirrorViewport").getMeasuredHeight()>=Math.round(90*c.getResources().getDisplayMetrics().density),"short-wide reader geometry");check(restored.back(),"reader/results back preserves data");return "PortfolioMirror Android screen PASS "+count;}finally{cleanup(store.filePath());}}
 public static void main(String[]args)throws Exception{count=0;String text=new String(Files.readAllBytes(Paths.get(args[0])),StandardCharsets.UTF_8);model(new JSONObject(text));if(args.length>1)Files.write(Paths.get(args[1]),text.getBytes(StandardCharsets.UTF_8));System.out.println("PortfolioMirror Java model/full-cross PASS "+count);}
}
